"""Read-only access to the template library generated by tools/extract_*.py."""
from __future__ import annotations

import json
from functools import lru_cache
from pathlib import Path

LIBRARY_DIR = Path(__file__).parent


@lru_cache
def work_package_library() -> dict:
    return json.loads((LIBRARY_DIR / "work_package_templates.json").read_text(encoding="utf-8"))


@lru_cache
def milestone_plan_template() -> dict:
    return json.loads((LIBRARY_DIR / "milestone_plan_template.json").read_text(encoding="utf-8"))
